 * How long a freshly issued session stays valid. The short lifetime is the
 * default; only a sign-in that ticked "remember me" earns the long one, so a
 * session started on a shared computer does not outlive the day.
 */
const SESSION_TTL_MS = 24 * 60 * 60 * 1000;
const REMEMBERED_SESSION_TTL_MS = 30 * 24 * 60 * 60 * 1000;

/** Length in bytes of the raw session token handed to the browser. */
const TOKEN_BYTES = 32;

/**
 * Mints a session. Only the hash reaches the database, so a dump of the
 * `sessions` table cannot be replayed as a login.
 */
export async function createSessionToken(
  userId: UserId,
  options: { rememberMe?: boolean } = {},
): Promise<{ token: string; expiresAt: IsoTimestamp }> {
  const token = randomToken(TOKEN_BYTES);
  const ttlMs =
    options.rememberMe === true ? REMEMBERED_SESSION_TTL_MS : SESSION_TTL_MS;
  const expiresAt = toIsoTimestamp(new Date(Date.now() + ttlMs));

  await sessionRepo.createSession(userId, hashToken(token), expiresAt);

  return { token, expiresAt };
}

