import { fileURLToPath } from "node:url";
import { defineConfig } from "vitest/config";
const root = process.env.PROJECT_ROOT!;
export default defineConfig({
  root,
  resolve: { alias: { "@": root + "/src" } },
  server: { fs: { strict: false } },
  test: { environment: "node", globals: true, include: ["/tmp/authcheck/**/*.test.ts"] },
});
EOF
cat > /tmp/authcheck/auth.test.ts <<'EOF'
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { eq } from "drizzle-orm";

const sent: { to: string; token: string }[] = [];
vi.mock("@/server/services/email-service", () => ({
  renderEmail: async (_t: string, props: Record<string, unknown>) => ({ subject: "s", html: String(props.token ?? ""), text: "" }),
  sendEmail: async (m: { to: string; html: string }) => { sent.push({ to: m.to, token: m.html }); },
}));

import { runMigrations } from "@/server/db/migrate";
import { getDb, sessions } from "@/server/db";
import { hashPassword, hashToken } from "@/lib/hash";
import { resetRateLimits } from "@/lib/rate-limit";
import * as userRepo from "@/server/repositories/user-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import { login, logout, requestPasswordReset, confirmPasswordReset } from "@/server/services/auth-service";
import { resolveSession, destroySession } from "@/server/services/session-service";
import { requestPasswordResetAction, confirmPasswordResetAction } from "@/actions/auth/reset-password";

let dir: string;
const PW = "Correct-horse-1234";
const NEW = "Another-horse-5678";
const H = 3_600_000;

beforeAll(async () => {
  dir = mkdtempSync(join(tmpdir(), "authcheck-"));
  process.env.TASKFLOW_DB_PATH = join(dir, "t.db");
  await runMigrations(process.env.TASKFLOW_DB_PATH);
  const h = await hashPassword(PW);
  await userRepo.insertUser({ email: "a@x.test", name: "A", passwordHash: h });
  await userRepo.insertUser({ email: "b@x.test", name: "B", passwordHash: h });
});
afterAll(() => rmSync(dir, { recursive: true, force: true }));
beforeEach(() => { resetRateLimits(); sent.length = 0; vi.useFakeTimers({ toFake: ["Date"] }); vi.setSystemTime(new Date("2026-03-15T12:00:00.000Z")); });
afterEach(() => vi.useRealTimers());

const li = (email: string, password = PW, rememberMe?: boolean) => login({ email, password, rememberMe } as never);

describe("auth", () => {
  it("logout only ends that session", async () => {
    const a1 = await li("a@x.test"); const a2 = await li("A@X.test"); const b = await li("b@x.test");
    await destroySession(a1.token);
    expect(await resolveSession(a1.token)).toBeNull();
    expect(await resolveSession(a2.token)).not.toBeNull();
    expect(await resolveSession(b.token)).not.toBeNull();
    await destroySession(a1.token); await destroySession("nope-nope");
    const row = getDb().select().from(sessions).where(eq(sessions.tokenHash, hashToken(a2.token))).get()!;
    await logout(row.id as never); await logout(row.id as never);
    expect(await resolveSession(a2.token)).toBeNull();
    expect(await resolveSession(b.token)).not.toBeNull();
    expect(await resolveSession((await li("a@x.test")).token)).not.toBeNull();
  });
  it("ttl", async () => {
    const s = await li("a@x.test"); const r = await li("a@x.test", PW, true);
    vi.advanceTimersByTime(24 * H - 1000);
    expect(await resolveSession(s.token)).not.toBeNull();
    vi.advanceTimersByTime(1000);
    expect(await resolveSession(s.token)).toBeNull();
    expect(await sessionRepo.purgeExpiredSessions(new Date().toISOString() as never)).toBeGreaterThanOrEqual(1);
    vi.advanceTimersByTime(29 * 24 * H - 1000);
    expect(await resolveSession(r.token)).not.toBeNull();
    vi.advanceTimersByTime(1000);
    expect(await resolveSession(r.token)).toBeNull();
  });
  it("reset flow", async () => {
    const a = await li("a@x.test"); const b = await li("b@x.test");
    await requestPasswordReset({ email: "A@x.test" }); await requestPasswordReset({ email: "b@x.test" });
    await requestPasswordReset({ email: "a@x.test" }); await requestPasswordReset({ email: "ghost@x.test" });
    expect(sent.map((m) => m.to)).toEqual(["a@x.test", "b@x.test", "a@x.test"]);
    const c = (token: string, password = NEW) => confirmPasswordReset({ token, password, confirmPassword: password });
    await expect(c(sent[0]!.token)).rejects.toThrow(/no longer valid/);
    vi.advanceTimersByTime(59 * 60_000);
    await c(sent[2]!.token);
    await expect(c(sent[2]!.token, "Third-horse-9999")).rejects.toThrow(/no longer valid/);
    expect(await resolveSession(a.token)).toBeNull();
    expect(await resolveSession(b.token)).not.toBeNull();
    await expect(li("a@x.test")).rejects.toThrow(/did not match/);
    await li("a@x.test", NEW);
    vi.advanceTimersByTime(60_000);
    await expect(c(sent[1]!.token)).rejects.toThrow(/no longer valid/);
    await li("b@x.test");
    // restore a's password
    await requestPasswordReset({ email: "a@x.test" }); await c(sent.at(-1)!.token, PW);
  });
  it("throttling is per account", async () => {
    let n = 0;
    for (; n < 200; n += 1) { try { await li("A@x.test", "wrong"); } catch (e) { if (/Too many/.test(String(e))) break; } }
    expect(n).toBe(30);
    await expect(li("a@x.test")).rejects.toThrow(/Too many/);
    await li("b@x.test");
    await requestPasswordReset({ email: "a@x.test" });
    expect(sent).toHaveLength(1);
    await confirmPasswordReset({ token: sent[0]!.token, password: PW, confirmPassword: PW });
    vi.advanceTimersByTime(H);
    await li("a@x.test");
    for (let i = 0; i < 20; i += 1) await requestPasswordReset({ email: "a@x.test" });
    expect(sent.filter((m) => m.to === "a@x.test")).toHaveLength(5);
    await requestPasswordReset({ email: "b@x.test" });
    expect(sent.at(-1)!.to).toBe("b@x.test");
    await confirmPasswordReset({ token: sent.at(-1)!.token, password: PW, confirmPassword: PW });
    await li("a@x.test");
  });
  it("actions are per address", async () => {
    for (let i = 0; i < 5; i += 1) expect((await requestPasswordResetAction({ email: "a@x.test" })).ok).toBe(true);
    expect((await requestPasswordResetAction({ email: "A@x.test" })).ok).toBe(false);
    expect((await requestPasswordResetAction({ email: "b@x.test" })).ok).toBe(true);
    expect((await confirmPasswordResetAction({ token: sent.at(-1)!.token, password: PW, confirmPassword: PW })).ok).toBe(true);
  });
